/// <summary>
///  This is an eventhandler for METHMIMItemMaterial Form.
/// </summary>
final class METHMIMItemMaterialForm_EventHandler
{
}

Method.Source:
    /// <summary>
    /// This is a lookup for EMS code spillage scheduleId.
    /// </summary>
    /// <param name="sender">sender.</param>
    /// <param name="e">event.</param>
    [FormControlEventHandler(formControlStr(HMIMItemMaterialList, METHMIMItemMaterial_EMSCodeSpillageSchedId), FormControlEventType::Lookup)]
    public static void METHMIMItemMaterial_EMSCodeSpillageSchedId_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        FormDataSource      metHMIMItemMaterial_ds = sender.formRun().dataSource(formDataSourceStr(HMIMItemMaterialList, METHMIMItemMaterial)) as FormDataSource;
        METHMIMItemMaterial   metHMIMItemMaterial  = metHMIMItemMaterial_ds.cursor();

        metHMIMItemMaterial.lookupEMSCodeSpillageSchedId(sender);
        FormControlCancelableSuperEventArgs cancelableSuperEventArgs = e as FormControlCancelableSuperEventArgs;
        cancelableSuperEventArgs.CancelSuperCall();
    }

    /// <summary>
    /// This will show the multi select option for lookup.
    /// </summary>
    /// <param name="sender">sender.</param>
    /// <param name="e">event.</param>
    [FormDataFieldEventHandler(formDataFieldStr(HMIMItemMaterialList, METHMIMItemMaterial, SubsideryHazard), FormDataFieldEventType::Modified)]
    public static void SubsideryHazard_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun formRun = sender.datasource().formRun();
        SysLookupMultiSelectCtrl multiSelectCtrl = formRun.parmMultiSelectCtrl();

        METHMIMItemMaterial metHMIMItemMaterial = formRun.dataSource(FormDataSourceStr(HMIMItemMaterialList, METHMIMItemMaterial)).cursor() as METHMIMItemMaterial;
        metHMIMItemMaterial.SubsideryHazard = con2Str(multiSelectCtrl.getSelectedFieldValues(), METConstants::AddressSeperator);
    }
